#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include "pa220_image.h"
static uint32_t crc(uint32_t c,const uint8_t*p,size_t n){size_t i;unsigned b;c^=0xffffffffU;for(i=0;i<n;i++){c^=p[i];for(b=0;b<8;b++)c=(c>>1)^((c&1)?0xedb88320U:0);}return c^0xffffffffU;}
static void be16(uint8_t*p,uint16_t v){p[0]=v>>8;p[1]=v;}
static void be32(uint8_t*p,uint32_t v){p[0]=v>>24;p[1]=v>>16;p[2]=v>>8;p[3]=v;}
static void be64(uint8_t*p,uint64_t v){be32(p,(uint32_t)(v>>32));be32(p+4,(uint32_t)v);}
#define CHECK(x) do { if(!(x)){fprintf(stderr,"FAIL line %d: %s\n",__LINE__,#x);return 1;} } while(0)
static int test_octeon(void){uint8_t b[200];struct pa220_image_info o;uint32_t c;memset(b,0,sizeof(b));be32(b+8,0x424f4f54);be16(b+16,192);be16(b+18,1);be16(b+20,2);be16(b+22,20021);be32(b+24,8);be64(b+32,0xffffffff80000000ULL);be16(b+44,2);memcpy(b+192,"PAYLOAD!",8);be32(b+28,crc(0,b+192,8));c=crc(0,b,12);c=crc(c,b+16,176);be32(b+12,c);CHECK(pa220_image_parse(b,sizeof(b),&o)==0);CHECK(o.format==PA220_IMAGE_OCTEON_BOOTLOADER);CHECK(o.board_compatible&&o.crc_valid&&o.image_type==2);CHECK(o.load_address==0xffffffff80000000ULL);be16(b+44,7);be32(b+12,0);c=crc(0,b,12);c=crc(c,b+16,176);be32(b+12,c);CHECK(pa220_image_parse(b,sizeof(b),&o)==0);CHECK(o.image_type==7);be16(b+22,1);be32(b+12,0);c=crc(0,b,12);c=crc(c,b+16,176);be32(b+12,c);CHECK(pa220_image_parse(b,sizeof(b),&o)==0);CHECK(!o.board_compatible);be16(b+16,16);CHECK(pa220_image_parse(b,sizeof(b),&o)!=0);b[199]^=1;CHECK(pa220_image_parse(b,sizeof(b),&o)!=0);return 0;}
static int test_uimage(void){uint8_t b[68],h[64];struct pa220_image_info o;memset(b,0,sizeof(b));be32(b,0x27051956);be32(b+12,4);be32(b+16,0x81000000);be32(b+20,0x81000000);b[28]=5;b[29]=5;b[30]=2;b[31]=0;memcpy(b+64,"DATA",4);be32(b+24,crc(0,b+64,4));memcpy(h,b,64);memset(h+4,0,4);be32(b+4,crc(0,h,64));CHECK(pa220_image_parse(b,sizeof(b),&o)==0);CHECK(o.format==PA220_IMAGE_LEGACY_UIMAGE&&o.architecture_compatible);b[65]^=1;CHECK(pa220_image_parse(b,sizeof(b),&o)!=0);return 0;}
static int test_fdt(void){uint8_t b[80];struct pa220_image_info o;memset(b,0,sizeof(b));be32(b,0xd00dfeed);be32(b+4,80);be32(b+8,56);be32(b+12,72);be32(b+16,40);be32(b+20,17);be32(b+24,16);be32(b+32,8);be32(b+36,16);CHECK(pa220_image_parse(b,sizeof(b),&o)==0);CHECK(o.format==PA220_IMAGE_FIT_FDT);be32(b+4,0xffffffff);CHECK(pa220_image_parse(b,sizeof(b),&o)!=0);return 0;}
static int test_elf32(void){uint8_t b[84];struct pa220_image_info o;memset(b,0,sizeof(b));b[0]=0x7f;b[1]='E';b[2]='L';b[3]='F';b[4]=1;b[5]=2;b[6]=1;be16(b+16,2);be16(b+18,8);be32(b+20,1);be32(b+24,0x81001000);be32(b+28,52);be16(b+40,52);be16(b+42,32);be16(b+44,1);be16(b+46,40);be16(b+48,0);be32(b+52,1);be32(b+56,80);be32(b+60,0x81001000);be32(b+64,0x81001000);be32(b+68,4);be32(b+72,8);be32(b+76,5);memcpy(b+80,"CODE",4);CHECK(pa220_image_parse(b,sizeof(b),&o)==0);CHECK(o.format==PA220_IMAGE_ELF32&&o.architecture_compatible);CHECK(o.segment_count==1&&o.segments[0].memory_size==8);be32(b+72,3);CHECK(pa220_image_parse(b,sizeof(b),&o)!=0);return 0;}
static int test_elf64(void){uint8_t b[128];struct pa220_image_info o;memset(b,0,sizeof(b));b[0]=0x7f;b[1]='E';b[2]='L';b[3]='F';b[4]=2;b[5]=2;b[6]=1;be16(b+16,2);be16(b+18,8);be32(b+20,1);be64(b+24,0xffffffff80001000ULL);be64(b+32,64);be16(b+52,64);be16(b+54,56);be16(b+56,1);be16(b+58,64);be16(b+60,0);be32(b+64,1);be32(b+68,5);be64(b+72,120);be64(b+80,0xffffffff80001000ULL);be64(b+88,0xffffffff80001000ULL);be64(b+96,8);be64(b+104,16);memcpy(b+120,"12345678",8);CHECK(pa220_image_parse(b,sizeof(b),&o)==0);CHECK(o.format==PA220_IMAGE_ELF64&&o.architecture_compatible&&o.segment_count==1);return 0;}
int main(void){CHECK(test_octeon()==0);CHECK(test_uimage()==0);CHECK(test_fdt()==0);CHECK(test_elf32()==0);CHECK(test_elf64()==0);puts("PA220 P7 image parser: 5 suites PASS");return 0;}
